#define SHARPNESS 1.5 / iResolution.y

float fCircle(vec2 pos, float r) {
    return length(pos) - r;
}

float fastAlphaMult2(float component, float alpha) {
    // Scale to 0-255 range, perform integer operations, then normalize back
    float c = component * 255.0;
    float a = alpha * 255.0;
    float temp = c * a;
    temp += 128.0;               // Add rounding factor
    temp += floor(temp / 256.0); // Equivalent to (temp >> 8) addition
    temp = floor(temp / 256.0);  // Right shift by 8 bits
    return temp / 255.0;         // Normalize to [0.0, 1.0]
}

vec4 Color(float f, vec4 col) {
    // Apply optimized alpha multiplication to each component
    float r = fastAlphaMult2(col.r, col.w);
    float g = fastAlphaMult2(col.g, col.w);
    float b = fastAlphaMult2(col.b, col.w);
    return vec4(vec3(r, g, b) * f, col.w); // Multiply by coverage 'f'
}

vec4 colCircle(vec2 pos, float r, vec4 col) {
    float c = smoothstep(SHARPNESS, 0.0, fCircle(pos, r));
    return Color(c, col);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec4 col = vec4(0.2);
    vec2 p = uv;
    const float numdots = 350.0;

    for (float i = 0.0; i < numdots; i++) {        
        p.x += cos(iTime * 0.1 + i) * 0.40;
        p.y -= sin(iTime * 0.4 + p.y) * 0.0012;
        col += colCircle(p, 0.02, vec4(0.5, i / numdots, 0.0, 0.5));
    }

    fragColor = col;
}
